//! Every `fixtures/session/*.json` (a vector, or a matrix of cases) through `core::session`; the
//! result must equal what the host's services returned. Generated by
//! `backend/test/engine-vectors/session-vectors.spec.ts`, see `docs/spec/session.md`.
mod common;
mod session_common;

use common::diff;
use serde_json::Value;
use std::path::PathBuf;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/session")
}

fn check(file: &str, kind: &str, name: &str, case: &Value, bad: &mut Vec<String>) {
    let got = session_common::run(kind, &case["input"]);
    let mut d = vec![];
    diff("", &got, &case["expected"], &mut d);
    if !d.is_empty() {
        bad.push(format!("{file}: {name}: {}", d.join("; ")));
    }
}

#[test]
fn session_vectors_match_the_host() {
    let mut files: Vec<_> = std::fs::read_dir(dir())
        .expect("fixtures/session")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "json"))
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no fixtures/session/*.json");
    let (mut bad, mut cases) = (vec![], 0);
    for f in &files {
        let v: Value = serde_json::from_str(&std::fs::read_to_string(f).unwrap()).unwrap();
        let file = f.file_name().unwrap().to_string_lossy().to_string();
        let kind = v["kind"].as_str().unwrap();
        match v["cases"].as_array() {
            Some(list) => {
                for c in list {
                    cases += 1;
                    check(&file, kind, c["name"].as_str().unwrap(), c, &mut bad);
                }
            }
            None => {
                cases += 1;
                check(&file, kind, v["name"].as_str().unwrap(), &v, &mut bad);
            }
        }
    }
    assert!(
        bad.is_empty(),
        "{} of {cases} cases differ:\n{}",
        bad.len(),
        bad.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}
